query:
SELECT DISTINCT ?person ?givenLabel ?familyLabel WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P735 ?given;
          wdt:P734 ?family.
  ?given rdfs:label ?givenLabel.
  ?family rdfs:label ?familyLabel.
  FILTER(LANG(?givenLabel) = "en")
  FILTER(LANG(?familyLabel) = "en")
}
LIMIT 10000
OFFSET 10000
